def correct_bracketing(brackets: str) -> bool:
    def contains_only_parentheses(s: str) -> bool:
        return all(c in ['(', ')'] for c in s)

    def count_brackets(s: str) -> tuple:
        open_count = s.count('(')
        close_count = s.count(')')
        return open_count, close_count

    def check_matching(s: str) -> bool:
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    if not contains_only_parentheses(brackets):
        return False

    open_count, close_count = count_brackets(brackets)
    if open_count != close_count:
        return False

    return check_matching(brackets)

